<?php
declare(strict_types=1);

// Each declared public method needs an explicit explanation and example.
$reference = [];
$group = static function (string $class, string $description, string $setup = '') use (&$reference): void {
    $reference['PBreeze\\' . $class] = ['description' => $description, 'setup' => $setup, 'methods' => []];
};
$method = static function (string $class, string $name, string $description, string $example) use (&$reference): void {
    $reference['PBreeze\\' . $class]['methods'][$name] = [$description, $example];
};

$group('Application', 'The application owns the explicitly wired services. Bootstrap returns an instance as $app. Its public readonly properties expose root/config, router, views, format, strings, session, db, mail, auth, encryption, botProtection, api, uploads, and log. Construction does not automatically connect to the database or create private storage.', '$app = require __DIR__ . "/bootstrap.php";');
$method('Application', '__construct', 'Build the services for an absolute project root and validated configuration array. Prefer bootstrap.php so environment files and mail settings are loaded consistently. Programmatic configuration keys are listed in the configuration chapter.', '$app = new \PBreeze\Application($root, $config);');
$method('Application', 'routes', 'Require routes/web.php and, when present, routes/api.php with $app, $router, and $api in scope. Call once per application instance; registering the same routes twice is an error.', '$app->routes();');
$method('Application', 'handle', 'Dispatch an already-created request and return a Response. Unsafe web methods must pass CSRF first; /api paths bypass web sessions and use the separate API router. This method does not start sessions or load routes and does not catch web exceptions.', '$response = $app->handle(new \PBreeze\Request("GET", "/health"));');
$method('Application', 'run', 'Run the web lifecycle: enforce production HTTPS settings, start a web session when appropriate, load routes, capture the request, handle errors, and send the response. API requests remain stateless. Call only once from the front controller and do not echo before it.', '$app->run();');
$method('Application', 'errorResponse', 'Translate an exception to a web response. HttpException preserves its status and headers; other errors return a generic 500, or diagnostic text only when debug=true. The optional logger records unexpected failures; without it, reporting goes to PHP. Never enable debug in production.', '$response = \PBreeze\Application::errorResponse($error, logger: $app->log);');

$group('Env', 'Environment settings use process environment values first, then the loaded file, then the supplied default. No shell expansion or interpolation occurs. Do not print secret values.');
$method('Env', 'load', 'Replace the in-memory file values with KEY=value entries from a local file. Blank lines and comments are ignored; matching outer quotes are removed, while backslashes stay literal. A missing file leaves an empty file map; invalid lines or unmatched quotes throw RuntimeException.', '\PBreeze\Env::load($root . "/.env");');
$method('Env', 'get', 'Return the process/file value as a string, or the default only when the key is absent. An explicitly empty value remains empty. This method does not validate or cast the value.', '$name = \PBreeze\Env::get("APP_NAME", "PBreeze");');
$method('Env', 'bool', 'Read a boolean environment value using PHP boolean validation. Typical values include true/false, yes/no, on/off, and 1/0. Invalid boolean text throws RuntimeException instead of silently choosing a default.', '$debug = \PBreeze\Env::bool("APP_DEBUG", false);');

$group('Strings', 'Stateless native UTF-8 string operations, available as $app->strings and reserved $strings in PHP/Breeze templates. Invalid UTF-8 throws InvalidArgumentException. Case conversion needs mbstring; grapheme slicing, naming, and transliteration need intl. These operations do not escape HTML or sanitize SQL, URLs, or paths.', '$strings = $app->strings;');
$method('Strings', 'lower', 'Return Unicode lowercase using mbstring and explicit UTF-8. Locale-independent mappings can change character length; no global encoding/locale setting changes.', '$text = $app->strings->lower("ÉLÈVE"); // élève');
$method('Strings', 'upper', 'Return Unicode uppercase using mbstring. Some characters expand, for example ß becomes SS. Not locale-specific casing.', '$text = $app->strings->upper("Straße"); // STRASSE');
$method('Strings', 'title', 'Return Unicode title case with mbstring, lowercasing other letters according to its word rules. Not language-specific editorial title capitalization.', '$text = $app->strings->title("hello WORLD"); // Hello World');
$method('Strings', 'trim', 'Remove leading/trailing Unicode whitespace and separator characters. Interior whitespace and zero-width marks remain. No custom character-mask interpretation occurs.', '$text = $app->strings->trim("\u{00a0} Ada \u{2003}"); // Ada');
$method('Strings', 'length', 'Count visible Unicode grapheme clusters with Intl. Combining accents and joined emoji count as one cluster. Empty text returns 0; this is not byte length.', '$length = $app->strings->length("e\u{0301}"); // 1');
$method('Strings', 'slice', 'Return a grapheme-safe substring. Offsets are zero-based and negative offsets count from the end. Null length includes the remainder; negative length excludes trailing clusters. Out-of-range offsets return empty text.', '$text = $app->strings->slice("Hello world", -5); // world');
$method('Strings', 'contains', 'Return whether text contains a literal, case-sensitive needle. Empty needles return true. No regex, case folding, or canonical Unicode normalization is performed.', '$found = $app->strings->contains("Hello café", "café"); // true');
$method('Strings', 'startsWith', 'Return whether text begins with an exact prefix. Case-sensitive and literal; empty prefix returns true even for empty text.', '$matches = $app->strings->startsWith("report.csv", "report"); // true');
$method('Strings', 'endsWith', 'Return whether text ends with an exact suffix. Case-sensitive and literal; empty suffix returns true.', '$matches = $app->strings->endsWith("report.csv", ".csv"); // true');
$method('Strings', 'before', 'Return text before the first literal delimiter, excluding it. If absent, return the original text. A delimiter at the beginning yields empty text; empty delimiters throw.', '$text = $app->strings->before("one/two/three", "/"); // one');
$method('Strings', 'after', 'Return text after the first literal delimiter, excluding it. If absent, return the original text. A delimiter at the end yields empty text; empty delimiters throw.', '$text = $app->strings->after("one/two/three", "/"); // two/three');
$method('Strings', 'replace', 'Replace all nonoverlapping exact case-sensitive search occurrences. Replacement is literal, not a regex replacement expression. Empty replacement deletes matches; empty search throws.', '$text = $app->strings->replace("Hello Ada, Ada!", "Ada", "Lin"); // Hello Lin, Lin!');
$method('Strings', 'truncate', 'Return text unchanged if it fits, otherwise limit total grapheme count including the suffix. Default suffix is three periods. Oversized suffix is cut to fit; zero limit returns empty for nonempty input, negative limits throw.', '$text = $app->strings->truncate("Hello world", 8); // Hello...');
$method('Strings', 'slug', 'Transliterate with ICU to lowercase ASCII letters/digits, collapse other runs into the selected separator, and trim outer separators. Only hyphen/underscore separators are accepted. Can return empty; uniqueness and accepted-empty handling belong to the application. ICU versions may change transliteration.', '$slug = $app->strings->slug("Crème brûlée!"); // creme-brulee');
$method('Strings', 'snake', 'Split separators, lower-to-upper boundaries, and acronym-to-word boundaries, lowercase Unicode words, and join with underscores. Retains Unicode letters/marks/numbers, without transliteration. Separator-only input returns empty.', '$name = $app->strings->snake("HTTPServerID"); // http_server_id');
$method('Strings', 'studly', 'Split naming words with the same rules as snake(), uppercase each first grapheme, lowercase the remainder, and concatenate. Acronyms normalize to ordinary words; Unicode is retained.', '$name = $app->strings->studly("hello-world"); // HelloWorld');
$method('Strings', 'camel', 'Create Studly words and lowercase the first grapheme, returning lower camel case. Empty or separator-only input returns empty; this is not programming-language identifier validation.', '$name = $app->strings->camel("HTTP_server_ID"); // httpServerId');
$method('Strings', 'random', 'Generate cryptographic text with random_bytes and unbiased rejection sampling. Length is 1..65536; alphabet is 2..94 unique printable non-space ASCII characters. Invalid options throw and entropy-source errors propagate. No expiry, storage hashing, or authorization is added.', '$token = $app->strings->random(64, "0123456789abcdef"); // Keep secret.');

$group('Request', 'A request separates query parameters, parsed body fields, headers, client IP, and uploads. Public method/path properties are readonly. Values are untrusted: validate before use. Native uploads are POST multipart only.');
$method('Request', '__construct', 'Create an explicit request, commonly for tests. Headers are keyed in lowercase; query/body are associative arrays and uploads maps field names to lists of UploadedFile objects. Construction alone does not normalize or validate the path like capture() does.', '$request = new \PBreeze\Request("POST", "/greet", body: ["name" => "Ada"]);');
$method('Request', 'capture', 'Build a request from PHP server globals, rejecting malformed URLs. JSON must be an object and is decoded at depth 32; API bodies are JSON-only and at most 1 MiB. Web POSTs above post_max_size return 413. Multipart metadata is normalized separately; malformed file structures return 400.', '$request = \PBreeze\Request::capture();');
$method('Request', 'input', 'Return one parsed body field, or the default when absent or null. It never falls back to the query string, so query parameters cannot silently override submitted values. Returned values may be arrays or objects and still need validation.', '$name = $request->input("name", "");');
$method('Request', 'query', 'Return one query-string value with an optional default. The method does not sanitize, convert, or validate types; use explicit checks for pagination and filters.', '$page = $request->query("page", "1");');
$method('Request', 'all', 'Return the parsed request body array only. Query parameters and uploaded files are excluded. Never mass-assign this result to a model without validation and an explicit field selection.', '$errors = \PBreeze\Validator::errors($request->all(), ["name" => "required|string"]);');
$method('Request', 'header', 'Read a header using a case-insensitive name, returning null when absent. Capture normalizes HTTP headers, content type/length, and supported Authorization forwarding. Header values are untrusted.', '$type = $request->header("Content-Type");');
$method('Request', 'clientIp', 'Return the captured direct REMOTE_ADDR, or unknown when unavailable. Forwarded-IP headers are deliberately not trusted; clients behind a reverse proxy may share the same limiter identity.', '$ip = $request->clientIp();');
$method('Request', 'file', 'Return the single nonempty selection for a file field, or null when no file was selected. More than one file produces HTTP 400. A returned object may contain a PHP upload error; validate it before storing.', '$file = $request->file("document");');
$method('Request', 'files', 'Return all nonempty selections for a field as a list, or an empty list. One-dimensional array fields are supported. Enforce your own expected count and combined-byte quota.', '$files = $request->files("documents");');
$method('Request', 'withApiUser', 'Internal authentication bridge: clone the request and attach a verified bearer-token identity containing id, name, email, and token_id. It does not validate a token itself; application handlers must not forge identities.', '$authenticated = $request->withApiUser($app->api->tokens->authenticate($request->header("Authorization")));');
$method('Request', 'apiUser', 'Return the bearer identity attached by API authentication. Throws LogicException on public API routes or ordinary web requests without such an identity. This is not a replacement for record-level authorization.', '$ownerId = $request->apiUser()["id"];');

$group('Response', 'Response values have readonly body, status, and headers. Return them from handlers; the application sends them once. Default security headers and no-store caching are applied by send().');
$method('Response', '__construct', 'Construct a response with an HTTP status from 100 through 599. The default content type is HTML UTF-8. Invalid header names or CR/LF/NUL in values throw InvalidArgumentException, preventing header injection.', '$response = new \PBreeze\Response("Saved.", 201, ["Content-Type" => "text/plain; charset=UTF-8"]);');
$method('Response', 'json', 'Encode an array to JSON with exceptions on unsupported/invalid data and set application/json UTF-8. Array/list shape determines JSON object/array output. JSON_HEX_TAG and JSON_HEX_AMP protect embedded angle brackets/ampersands; this is not HTML template escaping.', 'return \PBreeze\Response::json(["data" => ["id" => 42]], 201);');
$method('Response', 'redirect', 'Return a local redirect, defaulting to 303 for POST/redirect/GET. Only 301, 302, 303, 307, and 308 are accepted. Paths must begin with one slash, not two, and cannot contain whitespace, controls, or backslashes.', 'return \PBreeze\Response::redirect("/account");');
$method('Response', 'send', 'Set status and headers, then echo the body unless head=true. Framework defaults include CSP, nosniff, frame denial, referrer policy, permissions policy, and no-store unless explicitly overridden. Call before any output; normal controllers should return the response instead.', '$response->send(head: $request->method === "HEAD");');
$group('HttpException', 'An expected HTTP failure carries a readonly status and optional response headers. Web handlers display its message; keep it safe for the user.');
$method('HttpException', '__construct', 'Create an HTTP error to throw from a handler. Choose a valid error status and optional headers such as Retry-After or Allow. Unlike an unexpected exception, its message may be sent directly to the client.', 'throw new \PBreeze\HttpException(404, "Document not found.");');

$group('Router', 'Web routes are registered explicitly in order. Specific routes should precede parameterized routes. Handler arguments are Request followed by path parameters in declaration order.');
$method('Router', 'get', 'Register a GET handler at a local path. HEAD falls back to GET unless an explicit HEAD route exists. A handler must return a Response; trailing slashes are equivalent.', '$app->router->get("/hello/{name}", static fn (\PBreeze\Request $r, string $name): \PBreeze\Response => new \PBreeze\Response(e($name)));');
$method('Router', 'post', 'Register a POST handler. The application checks CSRF before dispatching ordinary web POSTs. Registration alone does not install authentication or bot protection.', '$app->router->post("/notes", [$controller, "store"]);');
$method('Router', 'add', 'Register another HTTP method or use the general registration API. Paths support named single-segment parameters, not custom regex. Duplicate/invalid definitions throw rather than replacing an existing route.', '$app->router->add("DELETE", "/notes/{id}", [$controller, "destroy"]);');
$method('Router', 'dispatch', 'Match a request and invoke its handler. Missing paths throw HTTP 404; a known path with the wrong method throws 405 with Allow. Direct dispatch does not enforce sessions, CSRF, or application error handling.', '$response = $app->router->dispatch(new \PBreeze\Request("GET", "/health"));');
$method('Router', 'listing', 'Return the registered method/path pairs for diagnostics and CLI listing. It does not execute handlers or expose their callable internals.', '$routes = $app->router->listing();');

$group('Validator', 'Validation reports errors; it does not transform input or authorize access. Supported rules are required, string, email, integer, min, max, and confirmed.');
$method('Validator', 'errors', 'Return field => list-of-message errors, or an empty array when valid. Separate rules with |. min/max measure Unicode string characters, not numeric magnitude. Optional missing/empty values skip rules other than required; confirmed compares field_confirmation. Unknown rules and malformed min/max arguments throw InvalidArgumentException.', '$errors = \PBreeze\Validator::errors($request->all(), ["name" => "required|string|min:2|max:80", "email" => "required|email"]);');

$group('Session', 'The session service stores native PHP session state. The application starts sessions for web requests, not for stateless API calls. Do not store large files or secret application keys in session data.');
$method('Session', 'start', 'Start a strict, cookie-only pbreeze_session with HttpOnly, SameSite=Lax, path=/, and optional Secure. An already-active session is left running. Call before output and set secure=true under HTTPS.', '$app->session->start(secure: true);');
$method('Session', 'get', 'Read a session value or default when missing/null. Values are not automatically removed, validated, or encrypted.', '$notice = $app->session->get("notice", "");');
$method('Session', 'put', 'Assign a value to the active session map. Native PHP serialization rules apply. This is not a flash-message API; clear one-time values explicitly.', '$app->session->put("notice", "Your changes were saved.");');
$method('Session', 'regenerate', 'Regenerate the native session ID and destroy the previous session file. Requires an active session; failures throw RuntimeException. Existing session data stays intact.', '$app->session->regenerate();');
$method('Session', 'reset', 'Clear all session values and regenerate the ID. Authentication uses this at login/logout so previous state, including the CSRF token, is discarded.', '$app->session->reset();');
$method('Session', 'token', 'Get the current CSRF token, creating 32 random bytes represented as hexadecimal when missing. Include it in a hidden form field or X-CSRF-Token, never in URLs.', '$token = $app->session->token();');
$method('Session', 'verifyCsrf', 'Skip GET/HEAD/OPTIONS, otherwise compare the header token (preferred) or _token body field using hash_equals. Invalid/missing tokens throw HTTP 419. A file upload still needs this check.', '$app->session->verifyCsrf($request);');

$group('BotProtection', 'CAPTCHA challenges are purpose-specific, session-bound, valid for five minutes, and consumed even on a failed answer. The website honeypot must remain an empty string. This does not replace CSRF, authorization, or rate limits.');
$method('BotProtection', '__construct', 'Bind bot protection to the application session. The session must be active before challenge state is persisted in HTTP use.', '$protection = new \PBreeze\BotProtection($app->session);');
$method('BotProtection', 'challenge', 'Create a six-character SVG challenge for a fixed lowercase form purpose. Return id and image URL. At most 12 active challenges are kept; more than 60 creations per minute in the session throws 429.', '$challenge = $app->botProtection->challenge("contact");');
$method('BotProtection', 'errors', 'Consume and validate _captcha_id, _captcha_answer, and empty website for the exact purpose. Return [] on success or a captcha error list on failure. Answers are case-insensitive. After any attempt issue a new challenge before redisplaying the form.', '$errors = $app->botProtection->errors($request, "contact");');
$method('BotProtection', 'forget', 'Discard the posted challenge only if it belongs to the supplied purpose. Useful when the user requests a fresh code rather than submitting the form. It does not validate the answer.', '$app->botProtection->forget($request, "contact");');
$method('BotProtection', 'image', 'Return the active session challenge as SVG with no-store/private and restrictive image headers. Unknown/expired IDs throw 404. The framework already registers the /captcha/{id} route.', 'return $app->botProtection->image($id);');

$group('View', 'Render trusted PHP/Breeze templates from an explicit view directory. Templates are application code, never user-supplied uploads. Configured Formatter and Strings services are available as reserved $format and $strings. View names are dot-separated, with no arbitrary filesystem paths.');
$method('View', '__construct', 'Set the view root, optional compilation cache directory, optional Formatter, and optional Strings service. The default cache is storage/views relative to the application view root; the default formatter uses en-US and UTC. If omitted, Strings is instantiated without changing global configuration.', '$views = new \PBreeze\View($root . "/app/views", formatter: $app->format, strings: $app->strings);');
$method('View', 'render', 'Resolve a dot name, preferring .breeze.php over .php, then render with the supplied data. Breeze source is compiled into a content-addressed PHP cache. Missing/invalid names, cycles, and unclosed captures throw.', '$html = $app->views->render("home", ["title" => "Welcome", "name" => "Ada"]);');
$method('View', 'evaluate', 'Internal renderer: resolve/compile one view and evaluate it inside an isolated output-buffer scope using the supplied TemplateContext. Data keys starting with __ are excluded and $format/$strings cannot be replaced. Prefer render() to preserve the layout lifecycle.', '$context = new \PBreeze\TemplateContext($app->views);' . "\n" . '$html = $app->views->evaluate("partials.footer", [], $context);');
$method('View', 'text', 'Convert a scalar, null, or Stringable value to text. Arrays and ordinary objects throw InvalidArgumentException. This performs no HTML escaping.', '$plain = \PBreeze\View::text(42); // "42"');
$method('View', 'escape', 'Validate/convert a template value with text(), then HTML-escape it with the global e() helper. Quotes are escaped and invalid UTF-8 is replaced, not executed.', '$safe = \PBreeze\View::escape("<strong>Ada</strong>");');
$method('View', 'clearCache', 'Delete only recognized content-addressed Breeze PHP cache files and return the number removed. Source templates are untouched. The next render recompiles on demand.', '$removed = $app->views->clearCache();');
$group('TemplateCompiler', 'Low-level trusted-template compiler. Prefer writing .breeze.php files and rendering through View; compilation is not a sandbox.');
$method('TemplateCompiler', 'compile', 'Convert Breeze source to PHP, translating supported directives, escaped expressions, raw output, and comments. The name is diagnostic context. Unsupported/malformed directives throw; execute the result only through the trusted view pipeline.', '$php = (new \PBreeze\TemplateCompiler())->compile("<p>{{ \$name }}</p>", "example");');
$group('TemplateContext', 'Internal layout/component state used by compiled Breeze templates. Most application code should use directives, not call these methods directly. Captures must be correctly nested and closed.');
$method('TemplateContext', '__construct', 'Create rendering state for a View and optional ancestor chain. The chain is used to reject recursion; normally leave it empty.', '$context = new \PBreeze\TemplateContext($app->views);');
$method('TemplateContext', 'render', 'Render a named view with independent frame bookkeeping and shared layout sections. Reject repeated names or depth 32 and clean up buffers/state on exit. This is the context-level equivalent of View::render().', '$html = $context->render("home", ["title" => "Home"]);');
$method('TemplateContext', 'extend', 'Select one parent layout for the current rendering frame. A second parent throws LogicException. Only invoke inside template evaluation; @extends is the user-facing form.', '$__engine->extend("layouts.app"); // Equivalent to @extends("layouts.app")');
$method('TemplateContext', 'startSection', 'Start an output capture for a named section. Names are validated and duplicate section declarations in the same frame throw. Pair with endSection(); use @section in normal templates.', '$__engine->startSection("content");');
$method('TemplateContext', 'endSection', 'Close the current section capture. Child sections win over parent defaults. Closing the wrong capture type throws LogicException.', '$__engine->endSection();');
$method('TemplateContext', 'yieldSection', 'Return a captured section as rendered HTML; if missing, return the HTML-escaped default. Sections contain trusted rendered template output. This powers @yield.', 'echo $__engine->yieldSection("title", "PBreeze");');
$method('TemplateContext', 'includeView', 'Render a partial in an independent context with caller scope plus explicit data overrides. The ancestor chain remains protected against recursion. Layout/section state is not leaked across the include.', 'echo $__engine->includeView(get_defined_vars(), "partials.footer", ["year" => 2026]);');
$method('TemplateContext', 'startComponent', 'Begin capturing a component body with explicit data and named slots. Components do not implicitly inherit arbitrary caller data. Pair with endComponent().', '$__engine->startComponent("components.panel", ["title" => "Details"]);');
$method('TemplateContext', 'endComponent', 'Finish the current component and return its rendered HTML with slot and named-slot data. Misnested/unclosed slots throw rather than silently losing content.', 'echo $__engine->endComponent();');
$method('TemplateContext', 'startSlot', 'Begin a named slot directly inside a component. Names must be valid identifiers, cannot be slot, and cannot repeat in that component.', '$__engine->startSlot("footer");');
$method('TemplateContext', 'endSlot', 'Close the named slot and attach its captured HTML to the parent component. Call only after startSlot(); @endslot normally generates this call.', '$__engine->endSlot();');

$group('Database', 'A lazily opened PDO connection. SQLite, MySQL, SQL Server through PDO_SQLSRV, and PostgreSQL through PDO_PGSQL are supported; there is no global connection. Use prepared values and trusted identifiers. The encryption property supports encrypted ORM casts.');
$method('Database', '__construct', 'Configure root-relative SQLite paths or MySQL/SQL Server/PostgreSQL settings and optional Encryption. PostgreSQL uses sslmode (default verify-full) and optional sslrootcert; SQL Server uses encrypt/trust_server_certificate strings true or false. Construction stores configuration without connecting. Prefer $app->db for the configured connection.', '$db = new \PBreeze\Database($root, ["driver" => "sqlite", "database" => ":memory:"]);');
$method('Database', 'pdo', 'Open/cache PDO with exception mode, associative fetches, native prepares, and no fetch stringification. SQLite enables foreign keys and a five-second busy timeout; new files use 0600. Connection/configuration failures throw.', '$pdo = $app->db->pdo();');
$method('Database', 'execute', 'Prepare SQL and execute the supplied positional or named parameter values. Return PDOStatement for fetch/fetchAll/rowCount. Parameters protect values, not table names, order clauses, or entire SQL fragments.', '$rows = $app->db->execute("SELECT * FROM notes WHERE id = ?", [42])->fetchAll();');
$method('Database', 'table', 'Start an immutable table Query returning associative arrays. The table must be a simple SQL identifier; expressions and dotted prefixes are rejected.', '$query = $app->db->table("notes");');
$method('Database', 'transaction', 'Begin a transaction, call the callback with PDO, commit on success, and return its result. On Throwable, roll back when active and rethrow. Nested transactions/savepoints are not implemented; MySQL DDL may auto-commit.', '$id = $app->db->transaction(fn (\PDO $pdo) => $app->db->table("notes")->insert(["title" => "Hello"]));');
$method('Database', 'driver', 'Return the configured driver name: sqlite, mysql, sqlsrv, or pgsql. This does not open a database connection. Connection-time validation rejects unsupported driver names.', '$driver = $app->db->driver();');
$method('Database', 'insert', 'Insert one associative array of scalar/null values into a simple table identifier using typed parameters. Return the requested identity as int/string; identity=null requests no ID and returns 0. PostgreSQL uses RETURNING. SQL Server uses OUTPUT INSERTED and does not support enabled INSERT triggers through this path. Normally use table()->insert().', '$id = $app->db->insert("notes", ["title" => "First note"]);');
$method('Database', 'limit', 'Build a limit for a trusted SELECT SQL string without executing it. Limit must be positive, offset nonnegative. SQL Server uses TOP for zero offset and OFFSET/FETCH otherwise; callers must provide ORDER BY when using a nonzero offset. Other drivers use LIMIT/OFFSET. This is not a parser or sanitizer for user SQL.', '$sql = $app->db->limit("SELECT id FROM notes ORDER BY id", 20, 40);');
$method('Database', 'ensureRateLimit', 'Internal atomic initializer for a rate-limit bucket with a primary/unique bucket key and expires_at column. Existing rows are preserved. SQL Server uses UPDLOCK/HOLDLOCK to serialize competing inserts; ordinary database errors propagate. This alone does not increment or enforce the limit.', '$app->db->ensureRateLimit("api_limits", $bucketHash, $expiresAt);');
$group('Query', 'An immutable query builder: each filter/order/limit returns a clone, leaving the original reusable. Table queries return arrays; model queries hydrate model objects. No arbitrary raw expressions, joins, implicit relations, or OR builder are supplied.', '$query = $app->db->table("notes");');
$method('Query', '__construct', 'Bind a query to a Database, simple table identifier, and optional Model prototype. Prefer Database::table() or Model::query() so hydration and casts are wired correctly.', '$query = new \PBreeze\Query($app->db, "notes");');
$method('Query', 'identifier', 'Validate a simple ASCII SQL identifier and supported driver. Return double quotes for pgsql, square brackets for sqlsrv, backticks for sqlite/mysql. The default mysql preserves existing direct callers. Expressions, dotted identifiers, spaces, and arbitrary SQL are rejected.', '$quoted = \PBreeze\Query::identifier("created_at", "pgsql"); // "created_at"');
$method('Query', 'where', 'Add an AND comparison using two arguments for equality or three for an explicit operator. Supported operators: =, !=, <>, <, <=, >, >=, LIKE, NOT LIKE. Null supports only equality/inequality and maps to IS NULL/IS NOT NULL. Values are bound; encrypted model fields are not searchable.', '$query = $query->where("title", "LIKE", "%hello%")->where("id", ">", 5);');
$method('Query', 'whereNull', 'Add an AND IS NULL condition without binding a value. The original query remains unchanged. This tests SQL null, not an empty string.', '$query = $query->whereNull("deleted_at");');
$method('Query', 'whereNotNull', 'Add an AND IS NOT NULL condition. Use this instead of trying to compare null with > or LIKE.', '$query = $query->whereNotNull("published_at");');
$method('Query', 'whereIn', 'Add a bound IN condition from a list of at most 500 scalar values. Nulls and associative arrays are rejected; an empty list deliberately matches no rows. Encrypted model fields cannot use IN comparisons.', '$query = $query->whereIn("id", [1, 2, 3]);');
$method('Query', 'orderBy', 'Append ordering by a validated column and asc/desc direction. Repeated calls add tie-breakers. Encrypted model fields cannot be sorted; never pass user-provided SQL expressions.', '$query = $query->orderBy("created_at", "desc")->orderBy("id", "desc");');
$method('Query', 'limit', 'Set a positive result limit on a cloned query. A zero/negative limit throws InvalidArgumentException. This bounds rows returned, not a bulk mutation.', '$query = $query->limit(10);');
$method('Query', 'offset', 'Set a nonnegative offset on a clone. Reading with an offset requires an explicit limit; otherwise get() throws LogicException. Prefer stable ordering when paging.', '$rows = $query->orderBy("id")->limit(10)->offset(20)->get();');
$method('Query', 'get', 'Execute SELECT * with current AND conditions, ordering, limit, and offset. Return a list of arrays or hydrated models; no rows is an empty list. Database and cast errors are thrown.', '$rows = $query->orderBy("id")->limit(20)->get();');
$method('Query', 'first', 'Read at most one matching row/model and return null if none exists. It applies limit(1) to a clone and leaves the original query untouched.', '$note = $query->where("title", "Hello")->first();');
$method('Query', 'firstOrFail', 'Return the first matching row/model, or throw RecordNotFoundException. API error handling maps this exception to 404; web handlers must explicitly map it when appropriate.', '$note = $query->where("title", "Hello")->firstOrFail();');
$method('Query', 'find', 'Find one row using the model primary key or id for a plain table query, combined with existing conditions. Return null if absent. Accept integer or string identifiers.', '$note = $app->db->table("notes")->find(42);');
$method('Query', 'findOrFail', 'Find by primary key and throw RecordNotFoundException when missing. Other existing conditions still apply, making an owner filter useful before lookup.', '$note = $app->db->table("notes")->where("user_id", $userId)->findOrFail($id);');
$method('Query', 'count', 'Count all matching rows using only the WHERE conditions. Ordering, limit, and offset do not change this total. Returns an integer.', '$total = $query->where("user_id", $userId)->count();');
$method('Query', 'exists', 'Return whether any row matches the current conditions using SELECT 1 LIMIT 1. This avoids hydrating a full result set.', '$hasNotes = $query->where("user_id", $userId)->exists();');
$method('Query', 'paginate', 'Return data, total, per_page, current_page, and last_page. perPage must be 1..100 and page positive without offset overflow. If no sort was chosen, order by primary key; an empty result has last_page=1.', '$page = $query->paginate(perPage: 20, page: 2);');
$method('Query', 'insert', 'Insert a plain-table associative array and return the insert ID as int or string. identity defaults to id; use another column for a custom identity or null to request no ID and return 0. Model queries reject insert(); use create() instead. Inserts cannot have filters/order/limit/offset. Column names and scalar values are validated.', '$id = $app->db->table("notes")->insert(["title" => "First note"]);');
$method('Query', 'create', 'Create a new model through a model-bound query, applying fillable fields and casts. Plain table queries reject this; use insert(). Filtered/ordered/limited queries cannot be used for insertion.', '$note = $notes->query()->create(["title" => "First note"]);');
$method('Query', 'update', 'Update all matching rows and return the driver-reported affected count. Requires WHERE conditions and rejects ordering/limit/offset to avoid misleading scoped writes. Model-backed updates validate fillable fields/casts; they are bulk operations, not per-instance saves.', '$changed = $app->db->table("notes")->where("id", 42)->update(["title" => "Revised"]);');
$method('Query', 'delete', 'Delete matching rows and return the affected count. An unfiltered delete or a query with order/limit/offset throws; explicit WHERE is mandatory. This does not cascade application file deletion.', '$deleted = $app->db->table("notes")->where("id", 42)->delete();');

$group('Model', 'Subclass Model and explicitly set table, fillable, optional hidden/casts, timestamps, primaryKey, and incrementing. Instances require an explicit Database. Methods are final to keep persistence invariants. Load subclasses with require_once; there is no static global ORM.', <<<'PHP'
final class ManualNote extends \PBreeze\Model
{
    protected string $table = 'notes';
    protected array $fillable = ['title'];
}
$notes = new ManualNote($app->db);
PHP);
$method('Model', '__construct', 'Construct an unsaved model/prototype with an explicit Database. Validate table/key identifiers and encrypted-key restrictions. Abstract Model itself cannot be instantiated; use your declared subclass.', '$notes = new ManualNote($app->db);');
$method('Model', 'query', 'Start a model-bound immutable query that hydrates this subclass. It does not automatically filter by the current record; use an explicit primary-key/owner filter.', '$note = $notes->query()->find(42);');
$method('Model', 'keyName', 'Return the configured primary-key column, normally id. This is the column name, not the current record ID.', '$column = $notes->keyName();');
$method('Model', 'exists', 'Return whether this object represents a persisted model. It does not requery the database; an externally deleted row may still require refresh() to detect.', '$saved = $note->exists();');
$method('Model', 'create', 'Build a new instance of the same subclass, fill validated writable fields, insert, refresh, and return it. The prototype/current object is not mutated. Unknown/unfillable fields throw.', '$note = $notes->create(["title" => "A clear example"]);');
$method('Model', 'fill', 'Validate the entire input against fillable, primary-key rules, timestamps, and casts before assigning attributes. Returns the same object without saving. Unknown fields are rejected, not silently discarded.', '$note->fill(["title" => "Updated title"]);');
$method('Model', 'encodeFill', 'Internal bulk-write helper: validate writable fields and convert values to database scalars without mutating the model. Encrypted casts use contextual encryption and retain unchanged ciphertext. Prefer fill()/update() in user code.', '$encoded = $notes->encodeFill(["title" => "Safe title"]);');
$method('Model', 'hydrate', 'Internal hydration helper: turn a trusted database row with an integer/string primary key into a persisted subclass instance. Decode/validate casts and establish a clean baseline. Do not hydrate arbitrary request data as trusted persisted records.', '$note = $notes->hydrate(["id" => 42, "title" => "Loaded from the database"]);');
$method('Model', 'save', 'Insert an unsaved object or persist only dirty attributes of an existing one, applying automatic timestamps when enabled. Refresh afterward and return true. A deleted object cannot be saved again; missing persisted rows throw.', '$note->title = "Saved revision";' . "\n" . '$note->save();');
$method('Model', 'update', 'Require a saved record, then fill and save the supplied fields. Returns true on success and throws on invalid fields, state, or persistence errors.', '$note->update(["title" => "Updated and saved"]);');
$method('Model', 'delete', 'Delete this saved record by key, mark the object deleted/nonpersisted, and return true. Missing records and attempts on unsaved models throw. There is no soft-delete feature.', '$note->delete();');
$method('Model', 'refresh', 'Reload the saved row from the database, replacing attributes and clearing dirty state. Unsaved/deleted or missing records throw. Local unsaved changes are discarded.', '$note->refresh();');
$method('Model', 'dirty', 'Return changed database-form attributes compared with the last persisted/hydrated baseline. Casts may mean these are encoded values or ciphertext. Do not expose this diagnostic array directly to users.', '$changes = $note->dirty();');
$method('Model', '__get', 'Read a loaded attribute through its configured cast using normal property syntax. Unknown/unloaded fields throw LogicException rather than returning silent null.', '$title = $note->title; // Invokes __get("title")');
$method('Model', '__set', 'Assign through fillable/cast checks using normal property syntax. The assignment is in memory only until save(); immutable primary-key/timestamp protections still apply.', '$note->title = "Draft"; // Invokes __set("title", "Draft")');
$method('Model', '__isset', 'Return whether a loaded attribute exists and is not null, using PHP isset semantics. This is not a database existence query.', '$hasTitle = isset($note->title);');
$method('Model', 'toArray', 'Return decoded visible attributes, omitting hidden fields and serializing dates consistently. Hidden controls output only, not whether a value is stored/encrypted. Explicitly choose fields for sensitive exports.', '$visible = $note->toArray();');
$method('Model', 'jsonSerialize', 'Provide JsonSerializable output by delegating to toArray(). json_encode() therefore honors hidden fields and casts. Encoding can still throw for unsupported output values.', '$json = json_encode($note, JSON_THROW_ON_ERROR);');
$method('Model', 'assertSearchable', 'Internal guard rejecting comparisons, sorts, or relationship keys using encrypted fields. Randomized authenticated encryption cannot support ordinary equality/range searches. Nonencrypted fields pass without a return value.', '$notes->assertSearchable("title");');
$method('Model', 'hasMany', 'Protected relationship helper for saved models: return a query for related rows whose foreign key equals the local key (default current primary key). A null key returns an empty-match query. Related classes must be explicitly loaded Model subclasses.', 'public function comments(): \PBreeze\Query' . "\n" . '{ return $this->hasMany(Comment::class, "note_id"); }');
$method('Model', 'belongsTo', 'Protected relationship helper: match a related owner key (default related primary key) using this saved record foreign-key value. Return a Query, not a lazily loaded object; call first()/firstOrFail(). Null foreign keys produce an empty query.', 'public function author(): \PBreeze\Query' . "\n" . '{ return $this->belongsTo(User::class, "user_id"); }');
$group('RecordNotFoundException', 'Thrown when an ORM required lookup or persistence target is absent. It inherits RuntimeException; API handling maps it to HTTP 404, while custom web handlers should explicitly decide the appropriate response.');

$group('Migration', 'An abstract migration defines reversible schema operations. Generate a file and return an anonymous subclass. Methods receive native PDO; keep identifiers trusted and create new migration files for later schema changes.');
$method('Migration', 'up', 'Implement the forward schema change. Called once for a pending migration and recorded on success. SQLite/SQL Server/PostgreSQL DDL is transactional here; MySQL DDL may commit independently. PostgreSQL operations requiring nontransactional execution are not supported here. Write driver-appropriate SQL and back up before production changes.', 'public function up(\PDO $db): void' . "\n" . '{ $db->exec("CREATE TABLE examples (id INTEGER PRIMARY KEY, title VARCHAR(120) NOT NULL)"); }');
$method('Migration', 'down', 'Implement the rollback operation for the schema change. The latest batch is rolled back in reverse order. Destructive drops delete data; test rollback on a disposable database.', 'public function down(\PDO $db): void' . "\n" . '{ $db->exec("DROP TABLE examples"); }');
$group('Migrator', 'The migration runner discovers timestamped migration PHP files, keeps batch history, and coordinates a filesystem lock. Database changes need a backup and explicit production approval via the CLI.');
$method('Migrator', '__construct', 'Bind a Database and application root containing database/migrations and storage. It does not run schema operations during construction.', '$migrator = new \PBreeze\Migrator($app->db, $app->root);');
$method('Migrator', 'migrate', 'Run pending migrations in filename order, record a new batch, and return applied names. Repeat calls with no pending files return []. Lock conflicts, missing applied files, and migration errors throw.', '$applied = $migrator->migrate();');
$method('Migrator', 'rollback', 'Run down() for only the latest batch, reversing order, and return reverted names. This can destroy data and is not a restore-from-backup feature.', '$reverted = $migrator->rollback();');
$method('Migrator', 'status', 'Return migration-name => batch mappings, with null for pending files. This is diagnostic but may initialize migration bookkeeping; ensure the connection is appropriate.', '$status = $migrator->status();');

$group('Encryption', 'Native OpenSSL AES-256-GCM with authenticated context binding. APP_KEY must be base64: plus 32 random bytes. Invalid keys are reported on encryption/decryption, allowing unrelated features to operate without a configured key.');
$method('Encryption', '__construct', 'Store a configured key without exposing it through the debug view. An empty key is not usable for encryption. Prefer the already-configured $app->encryption service.', '$encryption = new \PBreeze\Encryption($configuredKey);');
$method('Encryption', 'generateKey', 'Return a new random base64:-prefixed 256-bit key. Store it outside version control and back it up securely. This does not modify .env or re-encrypt old records.', '$newKey = \PBreeze\Encryption::generateKey(); // Store securely; do not log it.');
$method('Encryption', 'encrypt', 'Encrypt UTF-8 or binary plaintext to a versioned pbreeze:v1: envelope containing a fresh nonce and authentication tag. Context is authenticated, not encrypted. Equal plaintext encrypts differently on repeated calls; retain the exact context to decrypt.', '$payload = $app->encryption->encrypt("Private note", "notes:body");');
$method('Encryption', 'decrypt', 'Authenticate and decrypt a valid envelope using the same key/context. Wrong key/context, tampering, malformed base64, or unsupported versions throw EncryptionException; never treat failure as empty plaintext.', '$plain = $app->encryption->decrypt($payload, "notes:body");');
$method('Encryption', '__debugInfo', 'Return a redacted diagnostic representation for var_dump(). The actual key is deliberately excluded. Avoid dumping service/config objects in production regardless.', '$safeDiagnostic = $app->encryption->__debugInfo();');
$method('Encryption', '__serialize', 'Always throw LogicException to prevent serializing the encryption service and its key. Store ciphertext or configuration references, not this object.', 'try { serialize($app->encryption); } catch (\LogicException $error) { /* Serialization is blocked. */ }');
$method('Encryption', '__unserialize', 'Always throw LogicException: reconstruct the service through trusted configuration rather than accepting a serialized service payload.', 'try { $app->encryption->__unserialize([]); } catch (\LogicException $error) { /* Deserialization is blocked. */ }');
$group('EncryptionException', 'An authenticated-encryption failure. It inherits RuntimeException. Catch only when the application can safely report/recover; never substitute a successful-looking plaintext value.');

$group('Auth', 'Authentication requires migrated users/auth token/rate-limit tables and a started native session. The existing controllers add CAPTCHA/CSRF and safe UI flows; direct service calls do not automatically add those layers. AuthException holds safe field errors.');
$method('Auth', '__construct', 'Bind Database, Session, Mailer, application URL, and production HTTPS policy for auth email links. Normally use $app->auth; mismatched roots/URLs can create invalid or insecure links.', '$auth = new \PBreeze\Auth($app->db, $app->session, $app->mail, "https://example.test", true);');
$method('Auth', 'user', 'Return id/name/email/email_verified_at for the active session, or null. Validate session version and idle/absolute timeouts against the database, refresh activity, and log out expired/revoked state. There is no password hash in the result.', '$user = $app->auth->user();');
$method('Auth', 'protect', 'Wrap a web handler in a login guard, requiring email verification by default. Guests redirect to /login and unverified users to /email/verify. verified=false allows signed-in unverified users; record-level authorization remains your responsibility.', '$app->router->get("/reports", $app->auth->protect([$controller, "index"]));');
$method('Auth', 'register', 'Validate name/email/password/password_confirmation, normalize email, hash the password, apply rate limits, and queue a single-use verification email transactionally. Existing email addresses do not disclose account existence. Does not log in the user or check CAPTCHA itself.', '$app->auth->register($request->all(), $request->clientIp());');
$method('Auth', 'login', 'Validate credentials, apply email/IP limits, verify/rehash the password, and reset session state before recording identity/version/timestamps. Invalid credentials throw AuthException. Verification is enforced by protect(), not by rejecting all unverified logins.', '$app->auth->login($request->all(), $request->clientIp());');
$method('Auth', 'logout', 'Clear session data and regenerate the ID, invalidating the current browser session and CSRF token. This does not revoke independent API bearer tokens.', '$app->auth->logout();');
$method('Auth', 'forgotPassword', 'Validate/normalize the email and rate-limit the request. Queue a reset link for an existing user without revealing whether the address exists. Tokens last 30 minutes and older tokens for the same purpose are removed.', '$app->auth->forgotPassword(["email" => $request->input("email")], $request->clientIp());');
$method('Auth', 'resendVerification', 'Require a signed-in user and apply per-user/IP limits. Queue another verification email only if still unverified. A new token invalidates previous tokens for that user/purpose.', '$app->auth->resendVerification($request->clientIp());');
$method('Auth', 'verifyEmail', 'Consume a valid unexpired verification token once and mark the user verified in a transaction. The token must have the generated format; invalid/reused/expired values throw AuthException. Does not automatically authenticate a guest.', '$app->auth->verifyEmail($request->input("token"), $request->clientIp());');
$method('Auth', 'resetPassword', 'Validate password/confirmation, consume the reset token once, save a new hash, increment session_version, and log out. Existing web sessions and API tokens become invalid. Submit token in the protected POST body, not a custom unguarded endpoint.', '$app->auth->resetPassword($request->all(), $request->clientIp());');
$group('AuthException', 'A rejected authentication action carries errors, status, and retryAfter. Display safe field errors and honor throttling; unexpected database or mail failures remain distinct exceptions.');
$method('AuthException', '__construct', 'Construct field => message-list errors with an HTTP status (default 422) and optional retry seconds. API handling converts these to structured details; web auth controllers render the appropriate page.', 'throw new \PBreeze\AuthException(["email" => ["Check the email address."]], 422);');

$group('Api', 'A separate stateless JSON router, with runtime authentication and OpenAPI metadata registered together. The public tokens property exposes the bearer-token service. No session cookies, CSRF, automatic CORS, or role/permission layer is supplied.');
$method('Api', '__construct', 'Build the API router and default ping/me/token routes using Database, View, name, docs enablement, and optional Logger. Prefer $app->api so configuration and logging match the application.', '$api = new \PBreeze\Api($app->db, $app->views, "Example API", false, $app->log);');
$method('Api', 'matches', 'Return true only for /api or paths starting /api/. This determines whether request capture and application handling use stateless JSON rules.', '$isApi = \PBreeze\Api::matches("/api/me");');
$method('Api', 'validate', 'Validate the request body with Validator rules, throw ApiValidationException on errors, and return only fields named by the rules. Values are not cast or sanitized. Use explicit authorization before persistence.', '$data = \PBreeze\Api::validate($request, ["title" => "required|string|max:120"]);');
$method('Api', 'add', 'Register an /api/... route, callable, and operation metadata containing summary, unique operationId, and responses. Bearer auth is on by default; authenticated=false explicitly makes it public. Path parameters/security are derived from registration. Handlers must return a JSON Response.', '$app->api->add("GET", "/api/status", static fn (\PBreeze\Request $r): \PBreeze\Response => \PBreeze\Response::json(["data" => "ready"]), ["summary" => "Service status", "operationId" => "serviceStatus", "responses" => ["200" => ["description" => "Ready"]]], false);');
$method('Api', 'dispatch', 'Serve enabled docs/spec or rate-limit and dispatch an API request. Catch expected/unexpected errors into JSON responses. Unexpected failures are safely logged; the default limiter is 120 requests per direct IP per calendar minute.', '$response = $app->api->dispatch(new \PBreeze\Request("GET", "/api/ping"));');
$method('Api', 'errorResponse', 'Map HTTP/Auth/validation/not-found exceptions to a JSON error envelope and preserve relevant headers. Unexpected errors return generic 500 regardless of debug; optional Logger handles safe reporting. Auth/validation errors include field details.', '$response = \PBreeze\Api::errorResponse($error, $app->log);');
$method('Api', 'openApi', 'Return the current OpenAPI 3.0.3 document as an array. It reflects registered runtime routes and bearer requirements. Load routes first; exporting does not require public HTTP docs to be enabled.', '$app->routes();' . "\n" . '$spec = $app->api->openApi();');
$method('Api', 'listing', 'Return registered API method/path pairs for diagnostics. Includes docs endpoints according to the implementation configuration. Does not invoke handlers.', '$routes = $app->api->listing();');
$group('ApiValidationException', 'The API validation failure contains errors as a readonly field => message-list map and is translated to HTTP 422.');
$method('ApiValidationException', '__construct', 'Create a validation exception with safe field messages. Prefer Api::validate() for routine input validation so field selection and error shape remain consistent.', 'throw new \PBreeze\ApiValidationException(["title" => ["This field is required."]]);');
$group('ApiTokens', 'Tokens belong to verified users. Only SHA-256 token hashes are persisted; the secret is shown once at issuance. Password resets invalidate all prior session-version-bound tokens. There are no built-in scopes or roles.');
$method('ApiTokens', '__construct', 'Bind the token store to a migrated Database. Prefer $app->api->tokens rather than opening a separate connection.', '$tokens = new \PBreeze\ApiTokens($app->db);');
$method('ApiTokens', 'create', 'Issue a token for an existing verified user. Name is 1..80 UTF-8 bytes without controls; days must be 1..365, default 30. Return token plus issuance metadata; reveal/store the secret securely once, never log it or expose a public issuer without authorization.', '$issued = $app->api->tokens->create($verifiedUserId, "integration", 30);');
$method('ApiTokens', 'authenticate', 'Parse and verify an Authorization: Bearer value, check hash/expiry/revocation/user verification/session version, and return id/name/email/token_id. Missing or invalid tokens produce HTTP 401 with bearer challenge.', '$identity = $app->api->tokens->authenticate($request->header("Authorization"));');
$method('ApiTokens', 'listing', 'Return a user token metadata list without any token secret/hash. Requires a valid positive user ID; this is an administrator/application API, not an ownership guard.', '$metadata = $app->api->tokens->listing($userId);');
$method('ApiTokens', 'revoke', 'Revoke an existing token by numeric ID. Validate the caller permission first; token IDs are not credentials. The current-token API route already uses authenticated identity to select the token.', '$app->api->tokens->revoke($tokenId);');

$group('Formatter', 'Display-only formatting uses native Intl and explicit locale/time zone. Defaults are en-US and UTC; no global locale/time zone is changed. Inputs are not parsed from localized text. Decimal/money rounding is exact string arithmetic.');
$method('Formatter', '__construct', 'Configure a language tag and IANA time zone, or use $app->format from APP_LOCALE/APP_TIMEZONE. Invalid syntax/zones throw. Missing Intl is reported on formatting, not construction.', '$format = new \PBreeze\Formatter("de-DE", "Europe/Berlin");');
$method('Formatter', 'date', 'Format a DateTimeInterface or Unix seconds using short/medium/long/full date style, default medium. Apply configured or per-call locale/time zone. Strings are not parsed and mutable date inputs are not changed.', '$text = $app->format->date(new \DateTimeImmutable("2026-11-13T15:45:00Z"), "long");');
$method('Formatter', 'time', 'Format only time using the requested style, default medium. Locale chooses 12/24-hour conventions and time-zone names; explicit time-zone override follows daylight-saving rules.', '$text = $app->format->time($date, "short", timezone: "America/New_York");');
$method('Formatter', 'dateTime', 'Format date and time together (medium/short defaults), or use a custom ICU pattern up to 256 bytes. One part may be none; both none requires a pattern. Patterns are ICU, not PHP date() syntax. Uses Gregorian calendar.', '$text = $app->format->dateTime($date, timezone: "UTC", pattern: "yyyy-MM-dd HH:mm:ss");');
$method('Formatter', 'decimal', 'Format an integer or ASCII decimal string to exactly precision digits (0..20, default 2). Apply locale grouping/digits and half-away-from-zero rounding without converting the amount to float. Reject exponent notation, whitespace, and localized separators.', '$text = $app->format->decimal("1234.565", 2, "de-DE"); // 1.234,57');
$method('Formatter', 'percent', 'Treat input as a ratio, multiply by 100 exactly, and format localized percent output. precision/grouping work like decimal(); negative values rounding to zero lose the negative sign.', '$text = $app->format->percent("0.125", 1); // 12.5%');
$method('Formatter', 'money', 'Format a major-unit decimal string using an uppercase three-letter currency code and ICU currency precision/symbol placement. No floats, conversion rates, cash rounding, or arithmetic. Unknown syntactically valid codes use ICU generic currency handling.', '$text = $app->format->money("1234.565", "USD"); // $1,234.57');
$method('Formatter', 'moneyMinor', 'Format an integer number of minor units using currency-specific scale, not a universal cents assumption. USD 12345 means 123.45; JPY 12345 means 12345; KWD 12345 means 12.345. PHP integer range limits apply.', '$text = $app->format->moneyMinor(12345, "USD"); // $123.45');

$group('UploadedFile', 'Represents one native PHP HTTP upload, including a possible PHP receive error. originalName and clientMediaType are untrusted client metadata; error is the native UPLOAD_ERR_* code. Only capture() can construct instances.');
$method('UploadedFile', 'capture', 'Internal normalization of $_FILES into field => list<UploadedFile>. Remove empty selections, strip client path components, preserve receive errors, and reject malformed/deeply nested structures. It does not approve content or trust client MIME/size.', '$files = \PBreeze\UploadedFile::capture($_FILES);');
$method('UploadedFile', 'validate', 'Validate HTTP provenance, actual size, nonempty content, allowed extension, detected MIME, image headers, and bounded Office package shape. Return extension/mime/size; invalid content gives 422 and size failures 413. Standalone default is 2 MiB; use Uploads::validate for the .env default.', '$metadata = $file->validate(["pdf"], 2097152);');
$method('UploadedFile', 'moveTo', 'Internal native move into an already-reserved private destination. This only enforces HTTP provenance and movement, not allowed types, size, permissions, or ownership. Application code should use Uploads::store instead of bypassing validation.', '$file->moveTo($reservedPrivatePath); // Internal use after validation and directory reservation.');
$method('UploadedFile', 'mediaType', 'Internal mapping from a supported lowercase extension to canonical response MIME. Unsupported extensions throw InvalidArgumentException; this mapping does not inspect a file.', '$mime = \PBreeze\UploadedFile::mediaType("pdf"); // application/pdf');
$group('StoredUpload', 'A readonly storage result containing key, originalName, mimeType, and size. Persist these with the owner in your own attachment model. Keys locate files but do not grant authorization.');
$method('StoredUpload', '__construct', 'Create a metadata value object. Construction does not create, validate, or prove existence of a file. Normally obtain it from Uploads::store().', '$metadata = new \PBreeze\StoredUpload($key, "report.pdf", "application/pdf", $size);');
$group('Uploads', 'Private storage under storage/uploads with random 64-hex keys and validated extensions. The readonly maxBytes setting comes from UPLOAD_MAX_BYTES for $app->uploads. No application routes, owner table, or malware scanner are installed automatically.');
$method('Uploads', '__construct', 'Bind an application root and positive per-file default byte limit. Does not create directories immediately. Standalone default is 2097152; Application passes its validated .env configuration.', '$uploads = new \PBreeze\Uploads($root, maxBytes: 2097152);');
$method('Uploads', 'validate', 'Validate without moving, using the configured maxBytes unless overridden. allowedTypes is mandatory and limited to supported types. Return extension/mime/size; use this before starting a multi-file batch.', '$metadata = $app->uploads->validate($file, ["jpg", "png"]);');
$method('Uploads', 'store', 'Validate then atomically reserve a random private directory, move the real upload, set file permissions, and return StoredUpload. Original filenames cannot overwrite each other. Clean up incomplete writes; disk/configuration failures throw. Batches/database writes are not transactional.', '$stored = $app->uploads->store($file, ["pdf", "docx"], maxBytes: 2097152);');
$method('Uploads', 'download', 'Resolve a strict random key and return an attachment Response with canonical MIME, safe filename headers, no-store, and nosniff. Invalid/missing/symlinked files give 404. Authorize the owner before calling; contents are read into memory.', 'return $app->uploads->download($attachment["storage_key"], $attachment["original_name"]);');
$method('Uploads', 'delete', 'Remove only the resolved stored file and its random directory. Invalid/missing keys give 404; storage failures throw. Authorize first and coordinate database deletion yourself; this is not reversible.', '$app->uploads->delete($attachment["storage_key"]);');

$group('Logger', 'Native structured daily JSON-line logs in private storage/logs. Eight ordered levels, UTC dates, five-day default retention, and key-based context redaction. Logging is not a general secret detector or access-log service.');
$method('Logger', '__construct', 'Bind a root, retentionDays (1..3650), and minimumLevel. Storage is created only on a written entry. Application values come from LOG_RETENTION_DAYS and LOG_LEVEL.', '$logger = new \PBreeze\Logger($root, 5, "info");');
$method('Logger', 'log', 'Write one JSON record with timestamp/level/message/context after severity filtering. Lock concurrent writers, use private permissions, then prune matching daily files outside the UTC retention window. Context supports arrays/scalars/null/Throwable, depth 8, max record 64 KiB; invalid data or I/O errors throw.', '$app->log->log("notice", "Import completed.", ["rows" => 120]);');
foreach ([
    'debug' => 'Development diagnostics; the lowest severity, useful for safe operational details.',
    'info' => 'A routine successful application event, such as a report being created.',
    'notice' => 'A normal but noteworthy event worth retaining above routine informational noise.',
    'warning' => 'An unexpected condition that can currently be handled, such as a delayed delivery.',
    'error' => 'An operation failed and needs investigation; automatic exception reporting uses this level.',
    'critical' => 'A serious failure affecting an important application capability.',
    'alert' => 'A condition requiring prompt operator action.',
    'emergency' => 'The highest severity, reserved for an unusable or broadly failing system.',
] as $level => $description) {
    $method('Logger', $level, $description . ' Delegates to log() with the same filtering, redaction, retention, and failure behavior. It returns no value.', '$app->log->' . $level . '("Safe application event.", ["record_id" => 42]);');
}
$method('Logger', 'report', 'Safely report an unexpected Throwable through an optional logger. Exception metadata contains class/file/line only, excluding message, trace, and arguments. If file logging fails, explicitly report a safe diagnostic to PHP error_log; without a logger use PHP directly.', '\PBreeze\Logger::report($error, $app->log);');

$group('Documents\\Documents', 'Factories create native in-memory files or builders. No external converters are invoked. Validate export sizes and select visible fields explicitly. Office needs zip; PDF needs iconv.');
$method('Documents\\Documents', 'json', 'Encode any JSON-serializable value as pretty UTF-8 JSON with a trailing newline and preserved floating zero fraction. Return DocumentFile. Invalid UTF-8, recursive data, nonfinite numbers, or unsupported values throw JsonException.', '$file = \PBreeze\Documents\Documents::json(["name" => "Ada", "active" => true]);');
$method('Documents\\Documents', 'csv', 'Export iterable list rows with explicit enclosure/CRLF and no backslash escape. Cells are strings, finite numbers, booleans, or null. Delimiters are comma/semicolon/tab/pipe. Formula protection prefixes dangerous string cells with an apostrophe unless explicitly disabled for trusted raw output.', '$file = \PBreeze\Documents\Documents::csv([["Name", "Total"], ["Ada", 12.5]]);');
$method('Documents\\Documents', 'xml', 'Export nested arrays using string keys as validated unprefixed element names and integer keys as item. Escape text, represent null as empty text, and limit nesting to 64. No raw markup/attributes/DTDs or namespace features are accepted.', '$file = \PBreeze\Documents\Documents::xml(["people" => [["name" => "Ada"]]], "report");');
$method('Documents\\Documents', 'pdf', 'Return an empty mutable PdfDocument builder for A4 text/headings/fixed-width tables. Call build() to get a file; Windows-1252 font limits apply.', '$pdf = \PBreeze\Documents\Documents::pdf();');
$method('Documents\\Documents', 'excel', 'Return an empty Spreadsheet builder. Add at least one named worksheet then call build() for a real .xlsx ZIP package; strings stay literal, not formulas.', '$book = \PBreeze\Documents\Documents::excel();');
$method('Documents\\Documents', 'word', 'Return a mutable WordDocument builder. Add headings/paragraphs/tables and call build() for a real .docx. Unicode support depends on reader fonts.', '$word = \PBreeze\Documents\Documents::word();');
$method('Documents\\Documents', 'text', 'Internal validation helper returning unchanged text only if valid UTF-8 with XML 1.0 allowed characters. Unsupported controls or invalid encodings throw InvalidArgumentException; data is not silently repaired.', '$text = \PBreeze\Documents\Documents::text("Café");');
$method('Documents\\Documents', 'escape', 'Internal XML text/attribute escaping after text validation. Preserve carriage returns as numeric entities. It returns markup-safe text, not a complete XML element.', '$xmlText = \PBreeze\Documents\Documents::escape("Sales & totals"); // Sales &amp; totals');
$method('Documents\\Documents', 'cell', 'Internal scalar-to-text conversion: null => empty, booleans => true/false, finite numbers => locale-independent text, valid strings => unchanged. Arrays, objects, and nonfinite numbers throw.', '$text = \PBreeze\Documents\Documents::cell(true); // "true"');
$method('Documents\\Documents', 'row', 'Internal shape check requiring an array with sequential list keys. It does not validate each cell; individual writers do that. Throws InvalidArgumentException for associative arrays/nonarrays.', '\PBreeze\Documents\Documents::row(["Ada", 12.5]);');
$method('Documents\\Documents', 'package', 'Internal Office ZIP assembly from trusted part-name => XML-string data. Requires native zip, uses/removes a temporary file, and returns DocumentFile. It does not validate an arbitrary OOXML schema; prefer excel()/word() builders.', '$file = \PBreeze\Documents\Documents::package($trustedParts, "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "docx");');
$group('Documents\\DocumentFile', 'A complete in-memory file with readonly contents, mimeType, and extension. Files can be saved exclusively or returned as safe HTTP attachments.');
$method('Documents\\DocumentFile', '__construct', 'Construct bytes plus a syntactically valid media type and lowercase alphanumeric extension. This does not inspect file content or write to disk. Normally use a Documents factory.', '$file = new \PBreeze\Documents\DocumentFile("Hello\n", "text/plain", "txt");');
$method('Documents\\DocumentFile', 'save', 'Create a new local file exclusively; existing files and symlinks are not overwritten. Parent must exist; separators are normalized and nonportable basenames/stream wrappers rejected. Write privately, remove partial output on failure, and throw rather than return false.', '$file->save($app->root . "/storage/report." . $file->extension);');
$method('Documents\\DocumentFile', 'download', 'Return an attachment Response with byte length, safe UTF-8 filename*, ASCII fallback, MIME, nosniff, and no-store. Filenames cannot contain paths/control characters. Give a matching extension and authorize before exposing private data.', 'return $file->download("report." . $file->extension);');
$group('Documents\\PdfDocument', 'A mutable native PDF 1.4 writer using A4 pages and Courier fonts. Text wraps and paginates automatically; unsupported Unicode throws instead of substituting glyphs. No HTML rendering, embedded fonts, images, encryption, signatures, or PDF/A.');
$group('Documents\\WordDocument', 'A mutable WordprocessingML builder with US Letter page dimensions and one-inch margins. Word handles pagination. Supports Unicode text, six heading levels, paragraphs, and equal-width bordered tables; no rich inline style or images.');
foreach (['PdfDocument' => 3, 'WordDocument' => 6] as $class => $levels) {
    $variable = $class === 'PdfDocument' ? '$pdf' : '$word';
    $method('Documents\\' . $class, 'heading', 'Append a heading at level 1 through ' . $levels . ' and return this builder. Invalid levels/text throw. This changes document content, not HTTP output.', $variable . '->heading("Sales report", 1);');
    $method('Documents\\' . $class, 'paragraph', 'Append a paragraph and return this builder. Preserve line breaks/tabs according to the writer; no HTML interpretation occurs. Text must meet the writer encoding limits.', $variable . '->paragraph("Prepared by the sales team.\nAll totals are in USD.");');
    $method('Documents\\' . $class, 'table', 'Append a table with nonempty string headers and iterable list rows of matching width. Cells support strings, finite numbers, booleans, and null. ' . ($levels === 3 ? 'PDF allows 1..10 fixed-width columns with separators; rows may cross pages and headers are not repeated.' : 'Word allows 1..63 equal-width bordered columns and a bold repeating header row.'), $variable . '->table(["Name", "Total"], [["Ada", 12.5], ["Lin", null]]);');
    $method('Documents\\' . $class, 'build', 'Assemble the current document and return a DocumentFile without resetting the builder. Empty documents are allowed. ' . ($levels === 3 ? 'PDF uses Windows-1252 fonts and native iconv.' : 'DOCX packaging requires native zip.'), '$file = ' . $variable . '->build();');
}
$group('Documents\\Spreadsheet', 'A mutable XLSX workbook with typed numeric/boolean/blank cells and literal strings. Not a formula/chart engine. No reading, macros, styling, or date-number formats; preserve long identifiers as strings.');
$method('Documents\\Spreadsheet', 'sheet', 'Append a uniquely named worksheet from iterable list rows. Names are case-insensitively unique and 1..31 UTF-16 units without reserved characters. Limits: 1,048,576 rows, 16,384 columns, 32,767 UTF-16 units per text cell. Invalid additions do not append a partial sheet.', '$book->sheet("People", [["Name", "Total", "Active"], ["Ada", 12.5, true]]);');
$method('Documents\\Spreadsheet', 'build', 'Require at least one worksheet and assemble a real XLSX package with relationships and content types. Return DocumentFile; missing native zip or package I/O failures throw.', '$file = $book->build();');

$group('Mail\\Mailer', 'High-level native mail service, available as $app->mail. The public store property exposes database metadata/queue operations. Database queueing always persists, even when immediate-send logging is disabled.');
$method('Mail\\Mailer', '__construct', 'Bind Database plus mail config (log, from, smtp, imap). No network connection is opened at construction. Prefer the application service.', '$mailer = new \PBreeze\Mail\Mailer($app->db, $app->config["mail"]);');
$method('Mail\\Mailer', 'compose', 'Validate a message-data array with only from/to/subject/text/html. to is a recipient list; omitted from uses configured MAIL_FROM. Return Message without sending or queueing. At least one body is required.', '$message = $app->mail->compose(["to" => ["ada@example.test"], "subject" => "Welcome", "text" => "Hello, Ada!"]);');
$method('Mail\\Mailer', 'queue', 'Persist an outgoing Message in emails with queued status and return the numeric ID. No SMTP connection is made. Apply migrations first and run a worker separately.', '$id = $app->mail->queue($message);');
$method('Mail\\Mailer', 'send', 'Send immediately through SMTP. With MAIL_LOG=true, first queue/claim and update delivery state, returning the stored ID; when disabled, send without database logging and return null. Exceptions mean failure/uncertain delivery, not a safe automatic retry.', '$id = $app->mail->send($message);');
$method('Mail\\Mailer', 'sendQueued', 'Atomically claim a queued outgoing ID, send over SMTP, and update sent/failed/uncertain state. Concurrent claims are rejected. A database failure after SMTP acceptance must be investigated before resending.', '$app->mail->sendQueued($emailId);');
$method('Mail\\Mailer', 'fetch', 'Fetch up to 1..1000 IMAP messages without setting Seen. MAIL_LOG=true imports/deduplicates by source key and adds id; false leaves id=null and no database import. Return incoming records with parsed content and raw bytes.', '$incoming = $app->mail->fetch(10);');
$group('Mail\\Message', 'An immutable outgoing mail value with from/to/subject/text/html and generated messageId. Supports plain text, HTML, or multipart alternative; no attachments, CC/BCC, or display-name addresses.');
$method('Mail\\Message', '__construct', 'Validate ASCII addresses, 1..100 recipients, a UTF-8 subject up to 500 bytes without controls, and a nonempty UTF-8 body up to 5 MiB combined. Optional Message-ID must meet the strict format; otherwise create a random one.', '$message = new \PBreeze\Mail\Message("noreply@example.test", ["ada@example.test"], "Welcome", "Hello, Ada!");');
$method('Mail\\Message', 'address', 'Validate one ASCII email address without display names or angle brackets, up to 254 bytes. Throws InvalidArgumentException; it does not prove a mailbox exists.', '\PBreeze\Mail\Message::address("ada@example.test");');
$method('Mail\\Message', 'wire', 'Build an RFC-style CRLF message with MIME, encoded UTF-8 subject, and base64 body parts. It does not send anything. Wire output contains private message content; do not log it.', '$raw = $message->wire();');
$group('Mail\\Smtp', 'Native stream-based SMTP transport with verified TLS/STARTTLS and bounded protocol handling. Use Mailer for queue state tracking.');
$method('Mail\\Smtp', '__construct', 'Store trusted SMTP configuration (host, port, encryption, username/password, timeout, ca_file). Connection and validation happen when sending. No insecure remote authentication is allowed.', '$smtp = new \PBreeze\Mail\Smtp($app->config["mail"]["smtp"]);');
$method('Mail\\Smtp', 'send', 'Connect, negotiate TLS/authentication as configured, submit Message, and close. A final SMTP acceptance is not proof of inbox delivery. DeliveryException.uncertain distinguishes a connection loss after DATA began; investigate before retrying.', '$smtp->send($message);');
$group('Mail\\DeliveryException', 'An SMTP delivery error with readonly uncertain. If true, SMTP may have accepted the message; blindly retrying can duplicate it.');
$method('Mail\\DeliveryException', '__construct', 'Create a delivery diagnostic and uncertainty flag. Mailer records failed or uncertain accordingly. Keep diagnostics restricted to operators.', '$error = new \PBreeze\Mail\DeliveryException("SMTP delivery was interrupted.", true);');
$group('Mail\\Imap', 'Native read-only IMAP inbox fetching through EXAMINE and BODY.PEEK. Does not mark messages read, delete them, or send mail.');
$method('Mail\\Imap', '__construct', 'Store trusted IMAP configuration including host/port/encryption/credentials/mailbox/max_bytes. ASCII or IMAP modified UTF-7 mailbox names are accepted; MIME is parsed after retrieval.', '$imap = new \PBreeze\Mail\Imap($app->config["mail"]["imap"]);');
$method('Mail\\Imap', 'fetch', 'Fetch 1..1000 messages, optionally skipping source hashes reported by known(). Without a known callback, return newest matching UIDs up to the limit. Enforce per-message configured size and 50 MiB batch bound; transport/protocol failures throw.', '$messages = $imap->fetch(10, $app->mail->store->known(...));');
$group('Mail\\Mime', 'A bounded native MIME parser for incoming messages. Parsing is not HTML sanitization, antivirus, or complete MIME attachment support. Treat all output as untrusted.');
$method('Mail\\Mime', 'parse', 'Return parsed headers/from/to/subject/message_id/text/html from raw message bytes. Handle supported MIME encodings/multipart forms within parser limits. Never echo incoming html directly into a page.', '$parsed = \PBreeze\Mail\Mime::parse($rawMessage);');
$group('Mail\\MailStore', 'Database queue/inbox operations used by Mailer. Prefer high-level send/sendQueued/fetch unless implementing an audited worker. Queue transitions are guarded against concurrent claims.');
$method('Mail\\MailStore', '__construct', 'Bind a Database with the emails migration applied. Construction performs no queries.', '$store = new \PBreeze\Mail\MailStore($app->db);');
$method('Mail\\MailStore', 'queue', 'Insert an outgoing message with queued status and zero delivery progress. Return its ID. This is storage only, not network delivery.', '$id = $app->mail->store->queue($message);');
$method('Mail\\MailStore', 'receive', 'Import an Imap::fetch record, including parsed content, source key, mailbox, UID/UIDVALIDITY, and base64 raw source. Concurrent duplicates return the existing ID; unrelated database failures rethrow.', '$id = $app->mail->store->receive($incomingRecord);');
$method('Mail\\MailStore', 'known', 'Check whether an IMAP source hash already exists. Used by fetch to avoid importing the same mailbox/UID identity twice.', '$known = $app->mail->store->known($sourceKey);');
$method('Mail\\MailStore', 'find', 'Read the complete stored email row by positive ID. Missing records throw RuntimeException. This includes sensitive bodies/headers and must be restricted to authorized users.', '$row = $app->mail->store->find($emailId);');
$method('Mail\\MailStore', 'claim', 'Read/reconstruct a queued outgoing Message, atomically transition it to sending, increment attempts, and return it. Wrong direction/status or a lost claim throws. Do not call merely to preview a message.', '$message = $store->claim($emailId); // Worker-only state transition.');
$method('Mail\\MailStore', 'complete', 'Transition a sending row to sent and record sent_at after actual SMTP acceptance. Throws if state changed. Never call to fake delivery or recover an uncertain send without evidence.', '$store->complete($emailId); // Only after SMTP acceptance.');
$method('Mail\\MailStore', 'fail', 'Transition a sending row to failed or uncertain according to DeliveryException. Save its error diagnostic. Other states are rejected.', '$store->fail($emailId, $deliveryError);');
$method('Mail\\MailStore', 'retry', 'Requeue failed outgoing mail. force=true additionally permits uncertain/sending recovery, which may duplicate delivery; verify SMTP state first. Received/sent messages cannot be requeued through this operation.', '$app->mail->store->retry($emailId);');
$method('Mail\\MailStore', 'listing', 'List recent metadata newest-first with a 1..1000 limit (default 50). Does not include full bodies; use find() only when necessary and authorized.', '$rows = $app->mail->store->listing(20);');
$method('Mail\\MailStore', 'pending', 'List queued outgoing numeric IDs oldest-first, up to a required 1..1000 limit. This does not claim them; each worker must still use claim/sendQueued.', '$ids = $app->mail->store->pending(20);');
$group('Mail\\MailSocket', 'Low-level protocol stream helper for the native SMTP/IMAP implementations. Applications should normally use Mailer. Credentials are public readonly protocol inputs: never dump or serialize this object.');
$method('Mail\\MailSocket', '__construct', 'Validate host/port/timeout/encryption, open a native socket, and verify certificates for immediate TLS. none is allowed only unauthenticated on localhost. Network warnings become safe RuntimeExceptions.', '$socket = new \PBreeze\Mail\MailSocket($trustedMailConfig);');
$method('Mail\\MailSocket', 'startTls', 'Upgrade the existing socket to verified TLS 1.2/1.3. Protocol code must first negotiate STARTTLS; this method alone does not send the SMTP/IMAP command.', '$socket->startTls(); // Only after a successful protocol STARTTLS response.');
$method('Mail\\MailSocket', 'write', 'Write all bytes, retrying partial writes. Timeout/closed connection throws RuntimeException. Caller supplies complete protocol framing and must not log credentials.', '$socket->write("NOOP\r\n"); // Protocol-specific example.');
$method('Mail\\MailSocket', 'line', 'Read one CRLF-terminated protocol line without its CRLF, default bound 8192 bytes. Closed/time-out/oversized lines throw rather than returning partial success.', '$line = $socket->line();');
$method('Mail\\MailSocket', 'bytes', 'Read exactly a protocol-declared nonnegative byte count, in chunks. Incomplete/closed connections throw. Only pass trusted bounded lengths established by the protocol parser.', '$literal = $socket->bytes($validatedLiteralLength);');
$method('Mail\\MailSocket', 'close', 'Close an open stream; repeat calls safely do nothing. Prefer explicit cleanup in finally so network resources are not retained until garbage collection.', '$socket->close();');
$method('Mail\\MailSocket', '__destruct', 'Automatically close the socket when destroyed. It delegates to close(); do not rely on destructor timing for protocol logout or delivery-state transitions.', 'unset($socket); // Destruction closes the remaining stream.');

$group('Console', 'CLI entry point behind php breeze. Commands validate arguments and use shell-free processes. See the command reference for every task, output, example, and destructive side effect.');
$method('Console', '__construct', 'Bind an initialized Application. Console.php is explicitly required by the breeze entry script, not by normal web bootstrap.', 'require_once $app->root . "/framework/Console.php";' . "\n" . '$console = new \PBreeze\Console($app);');
$method('Console', 'run', 'Run a list of arguments excluding the PHP/breeze executable names, defaulting to help. Return an exit code (usually 0); invalid input and command failures throw to the entry point. Production database changes require --force.', '$exitCode = $console->run(["help"]);');
$group('Mail\\MailConsole', 'Mail-specific CLI dispatcher. Normal usage is through php breeze mail:..., not a separate script.');
$method('Mail\\MailConsole', '__construct', 'Bind the application Mailer so mail CLI tasks use the same database/network configuration.', '$console = new \PBreeze\Mail\MailConsole($app->mail);');
$method('Mail\\MailConsole', 'run', 'Execute a validated mail command with optional argument and force flag. May read JSON files, inspect database records, send SMTP, or import IMAP depending on the command. Do not pass untrusted arbitrary commands or force retries automatically.', '$console->run("mail:list", "10", false);');
$group('Process', 'A shell-free child-process utility for CLI tasks. Executables/arguments remain separate, preserving special path characters. Do not accept arbitrary executable paths from users.');
$method('Process', 'run', 'Execute an argument list in an existing working directory using proc_open with inherited standard streams and no shell. Return the child exit status; startup failures throw. Requires proc_open and an allowed trusted executable.', '$status = \PBreeze\Process::run([PHP_BINARY, "-v"], $app->root);');
$group('Filesystem', 'Small portable filesystem helpers shared by database, generators, and private storage. They are not an arbitrary-path authorization layer.');
$method('Filesystem', 'databasePath', 'Resolve relative paths against a root, normalize backslashes, preserve :memory:, and recognize Linux/Windows drive/UNC absolute paths. Reject empty/NUL and drive-relative paths such as C:data.sqlite.', '$path = \PBreeze\Filesystem::databasePath($root, "database/app.sqlite");');
$method('Filesystem', 'permissions', 'Set POSIX modes on non-Windows systems and throw on chmod failure. Windows intentionally relies on NTFS ACLs instead; this method does not secure ACLs for you.', '\PBreeze\Filesystem::permissions($privateFile, 0600);');
$method('Filesystem', 'portableName', 'Reject Windows device-name segments such as CON, NUL, COM1, and LPT9 even on Linux. This helper alone does not reject every unsafe path character or validate a full filename.', '\PBreeze\Filesystem::portableName("ReportController");');

return [
    'classes' => $reference,
    'functions' => [
        'e' => [
            'Escape a string, integer, float, or null for HTML text/quoted attributes using UTF-8, both quote styles, and replacement for invalid bytes. It is not URL, JavaScript, CSS, or SQL escaping. Prefer escaped Breeze output; do not double-escape already-rendered markup.',
            'echo "<p>" . e($request->input("name", "")) . "</p>";',
        ],
        'csrf_field' => [
            'Return a hidden _token input with the session CSRF token HTML-escaped. The session must be active and the submitted request must pass Session::verifyCsrf. In Breeze the equivalent directive is @csrf($session), with the Session explicitly supplied.',
            'echo csrf_field($app->session);',
        ],
    ],
];
